function eifStep(v, I, dt, p) {
  // p = { C: 281, gL: 30, EL: -70.6, VT: -50.4, dT: 2, Vr: -70.6, Vpeak: 20 } (pF, nS, mV, ms)
  const exp = p.gL * p.dT * Math.exp(Math.min((v - p.VT) / p.dT, 30));
  v += dt * (-p.gL * (v - p.EL) + exp + I) / p.C;
  if (v >= p.Vpeak) return { v: p.Vr, spike: true };
  return { v, spike: false };
}
